const text = $input.item.json.data || '';
const lines = text.split(/\r?\n/).filter(Boolean);
if (!lines.length) return [];

const parseCsvLine = (line) => {
  const out = [];
  let value = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') quoted = !quoted;
    else if (c === ',' && !quoted) {
      out.push(value.trim().replace(/^"|"$/g, ''));
      value = '';
    } else value += c;
  }
  out.push(value.trim().replace(/^"|"$/g, ''));
  return out;
};

const headers = parseCsvLine(lines[0]);
return lines.slice(1).map(line => {
  const values = parseCsvLine(line);
  const json = {};
  headers.forEach((h, i) => json[h] = values[i] ?? '');
  return { json };
});

const items = $input.all();
const clientes = items.flatMap(i => {
  const j = i.json || {};
  return Array.isArray(j.clientes) ? j.clientes : (Array.isArray(j.body?.clientes) ? j.body.clientes : []);
});
const investimentos = items.flatMap(i => {
  const j = i.json || {};
  if (Array.isArray(j.investimentos)) return j.investimentos;
  if (j.produto) return [j];
  return [];
});

const fallback = [
  { perfil: 'Conservador', produto: 'CDB Liquidez Diária', minimo: 'R$ 1.000,00', rentabilidade: '12,5%' },
  { perfil: 'Moderado', produto: 'Fundos Imobiliários (FIIs)', minimo: 'R$ 5.000,00', rentabilidade: '9,8%' },
  { perfil: 'Arrojado', produto: 'Ações e Criptomoedas', minimo: 'R$ 10.000,00', rentabilidade: '15,0%' }
];

const catalogo = investimentos.length >= 3 ? investimentos : fallback;

const money = value => Number(String(value ?? '0')
  .replace('R$', '').replace(/\./g, '').replace(',', '.').trim()) || 0;

return clientes.map(cliente => {
  const saldo = money(cliente.saldo);
  const opcoes = catalogo.filter(x => x.perfil === cliente.perfil);
  const rec = opcoes.find(x => saldo >= money(x.minimo)) || opcoes[0] || fallback[0];

  return {
    json: {
      cliente: {
        nome: cliente.nome || 'Cliente',
        email: cliente.email || '',
        telegram_chat_id: cliente.telegram_chat_id || '',
        perfil: cliente.perfil || 'Geral',
        saldo: cliente.saldo || 'R$ 0,00',
        saldo_num: saldo
      },
      recomendacao: rec,
      regras: {
        saldo_atende_minimo: saldo >= money(rec.minimo),
        aviso: 'Conteúdo educacional. Não constitui recomendação financeira personalizada.'
      }
    }
  };
});

const xml = $input.item.json.data || '';
const matches = [...xml.matchAll(/<item>[\s\S]*?<\/item>/gi)].slice(0, 5);
const noticias = matches.map(m => {
  const item = m[0];
  const get = tag => (item.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i')) || [,''])[1]
    .replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim();
  return { titulo: get('title'), link: get('link'), data: get('pubDate') };
});
return [{ json: { noticias } }];

const item = $input.item.json;
const noticias = Array.isArray(item.noticias) ? item.noticias : Array.isArray(item.contexto_noticias) ? item.contexto_noticias : [];
const contextoNoticias = noticias.length ? noticias.slice(0, 5).map(n => `- ${n.titulo || 'Sem título'} | ${n.link || ''} | ${n.data || ''}`).join('
') : 'Nenhuma notícia disponível.';
const cliente = item.cliente || {};
const recomendacao = item.recomendacao || {};
const prompt = `Você é um assistente de comunicação de investimentos.

Gere uma mensagem curta, clara e profissional para o cliente abaixo.

REGRAS:
- Use SOMENTE os dados fornecidos.
- Não invente rentabilidade, valores, notícias ou fatos.
- Não transforme o texto em recomendação financeira personalizada.
- Explique a opção apresentada de forma educacional.
- Só mencione uma notícia se ela tiver relação evidente com o contexto.
- Não trate uma notícia como recomendação de compra ou venda.
- Não use markdown pesado.
- Responda apenas com a mensagem final em português do Brasil.

CLIENTE:
${JSON.stringify(cliente)}

OPÇÃO DO CATÁLOGO:
${JSON.stringify(recomendacao)}

NOTÍCIAS DISPONÍVEIS:
${contextoNoticias}

AVISO:
${item.regras?.aviso || 'Conteúdo educacional.'}`;
return [{
  json: { ...item, cliente, recomendacao, noticias, prompt, contexto_noticias: noticias }
}];

const original = $('Code - Prompt IA').item.json;
const text = $json.output || $json.text || 'Não foi possível gerar a mensagem com IA nesta execução.';

return [{
  json: {
    ok: true,
    cliente: original.cliente,
    recomendacao: original.recomendacao,
    noticias: original.contexto_noticias || [],
    mensagem: text,
    canais: {
      email: Boolean(original.cliente.email),
      telegram: Boolean(original.cliente.telegram_chat_id)
    },
    aviso: original.regras.aviso
  }
}];
